        n = len(startTime)
        gaps = [0] * (n + 1)
        gaps[0] = startTime[0]
        for i in range(1, n):
            gaps[i] = startTime[i] - endTime[i - 1]
        gaps[n] = eventTime - endTime[n - 1]

        # window of k+1 consecutive gaps (covering k meetings in between)
        window = sum(gaps[0:k + 1])
        best = window
        for i in range(k + 1, n + 1):
            window += gaps[i] - gaps[i - k - 1]
            if window > best:
                best = window
        return best
