from hypothesis import strategies as st


@st.composite
def gen(draw):
    E = draw(st.integers(3, 12))
    n = draw(st.integers(2, min(5, (E + 1) // 2)))
    k = draw(st.integers(1, n))
    # 2n distinct sorted points give strictly increasing start<end pairs
    # with end_i <= start_{i+1}, all inside [0, E].
    pts = draw(st.lists(st.integers(0, E), min_size=2 * n, max_size=2 * n,
                        unique=True).map(sorted))
    starts = pts[0::2]
    ends = pts[1::2]
    return f"{E}\n{k}\n{json.dumps(starts)}\n{json.dumps(ends)}"


def validate(inp):
    try:
        lines = inp.split("\n")
        if len(lines) < 4:
            return False
        E = json.loads(lines[0])
        k = json.loads(lines[1])
        s = json.loads(lines[2])
        e = json.loads(lines[3])
    except Exception:
        return False
    for v in (E, k):
        if not isinstance(v, int) or isinstance(v, bool):
            return False
    if not isinstance(s, list) or not isinstance(e, list):
        return False
    n = len(s)
    if len(e) != n or n < 2 or n > 10**5:
        return False
    if not (1 <= E <= 10**9):
        return False
    if not (1 <= k <= n):
        return False
    for x in s + e:
        if not isinstance(x, int) or isinstance(x, bool):
            return False
    for i in range(n):
        if not (0 <= s[i] < e[i] <= E):
            return False
        if i + 1 < n and e[i] > s[i + 1]:
            return False
    return True


def _feasible(E, S, starts, ends, L, R):
    # Can all meetings be placed in order, inside [0,E], avoiding the open
    # interval (L,R), where meetings whose index is not in S stay fixed?
    cur = 0
    for i in range(len(starts)):
        d = ends[i] - starts[i]
        if i in S:
            s = cur
            if s < R and s + d > L:
                s = R
            if s + d > E:
                return False
        else:
            s = starts[i]
            if s < cur:
                return False
            if s < R and s + d > L:
                return False
        cur = s + d
    return True


def ref(inp):
    lines = inp.split("\n")
    E = json.loads(lines[0])
    k = json.loads(lines[1])
    starts = json.loads(lines[2])
    ends = json.loads(lines[3])
    n = len(starts)
    subsets = []
    for size in range(0, k + 1):
        for comb in itertools.combinations(range(n), size):
            subsets.append(set(comb))
    best = 0
    for L in range(0, E + 1):
        for R in range(L, E + 1):
            if R - L <= best:
                continue
            for S in subsets:
                if _feasible(E, S, starts, ends, L, R):
                    best = R - L
                    break
    return json.dumps(best)
