    # the original relative order and non-overlap. A meeting whose placed
    # start differs from its original start counts as rescheduled.
    # Optimal placements can be taken at integer times (all data integer).
    placed = []

    def evaluate():
        nonlocal best
        moved = sum(1 for i in range(n) if placed[i] != start[i])
        if moved > k:
            return
        cur = 0
        g = 0
        for i in range(n):
            s = placed[i]
            e = s + dur[i]
            g = max(g, s - cur)
            cur = e
        g = max(g, event_time - cur)
        best = max(best, g)

    def dfs(i, prev_end):
        if i == n:
            evaluate()
            return
        for s in range(prev_end, event_time - dur[i] + 1):
            placed.append(s)
            dfs(i + 1, s + dur[i])
            placed.pop()

    dfs(0, 0)
    return json.dumps(best)
