@st.composite
def gen(draw):
    n = draw(st.integers(2, 4))
    durs = [draw(st.integers(1, 2)) for _ in range(n)]
    gaps = [draw(st.integers(0, 2)) for _ in range(n + 1)]
    T = sum(durs) + sum(gaps)
    E = draw(st.integers(T, T + 3))
    k = draw(st.integers(1, n))
