        ends.append(pos + durs[i])
        pos = pos + durs[i] + gaps[i + 1]
    # Ensure the event end is at least the last end time.
    E = max(E, ends[-1])
    return f"{E}\n{k}\n{json.dumps(starts)}\n{json.dumps(ends)}\n"

