            m = moved + (1 if s != s0[i] else 0)
            if m > k:
                continue
            starts.append(s)
            rec(i + 1, s + durs[i], m, starts)
            starts.pop()

    rec(0, 0, 0, [])
    return json.dumps(best[0])
